"use client";

import { useRouter } from "next/navigation";
import { Card } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import { ArrowRight } from "lucide-react";

/* ================= TYPES MATCH BACKEND ================= */

export interface Identity {
  id: string;
  identityId: string;
  confidence: string;
  consistency: number;
  detectionCount: number;
  firstSeen: string;
  lastSeen: string;
}

/* ======================================================= */

interface IdentityTableProps {
  identities: Identity[];
  isLoading?: boolean;
  currentPage?: number;
  itemsPerPage?: number;
  onPageChange?: (page: number) => void;
}

export function IdentityTable({
  identities,
  isLoading = false,
  currentPage = 1,
  itemsPerPage = 10,
  onPageChange,
}: IdentityTableProps) {
  const router = useRouter();

  /* ================= PAGINATION ================= */

  const paginatedIdentities = identities.slice(
    (currentPage - 1) * itemsPerPage,
    currentPage * itemsPerPage,
  );

  const totalPages = Math.ceil(identities.length / itemsPerPage);

  /* ================= HELPERS ================= */

  const formatDate = (dateString: string) => {
    return new Date(dateString).toLocaleString();
  };

  const getConfidenceBadge = (confidence: string) => {
    const value = parseFloat(confidence);

    if (value >= 0.9) return "bg-green-500/20 text-green-400";
    if (value >= 0.7) return "bg-yellow-500/20 text-yellow-400";

    return "bg-red-500/20 text-red-400";
  };

  /* ================= LOADING ================= */

  if (isLoading) {
    return (
      <Card className="bg-[#222] border-[#333]">
        <div className="p-6 space-y-4">
          {[...Array(5)].map((_, i) => (
            <Skeleton key={i} className="h-12 bg-[#333]" />
          ))}
        </div>
      </Card>
    );
  }

  /* ================= EMPTY STATE ================= */

  if (identities.length === 0) {
    return (
      <Card className="bg-[#222] border-[#333]">
        <div className="p-12 text-center">
          <p className="text-gray-400">No identities found</p>
        </div>
      </Card>
    );
  }

  /* ================= TABLE ================= */

  return (
    <Card className="bg-[#222] border-[#333] overflow-hidden">
      <div className="overflow-x-auto">
        <table className="w-full">
          <thead>
            <tr className="border-b border-[#333] bg-[#1a1a1a]">
              <th className="px-6 py-3 text-left text-sm font-semibold text-gray-300">
                Identity ID
              </th>

              <th className="px-6 py-3 text-left text-sm font-semibold text-gray-300">
                Detections
              </th>

              <th className="px-6 py-3 text-left text-sm font-semibold text-gray-300">
                First Seen
              </th>

              <th className="px-6 py-3 text-left text-sm font-semibold text-gray-300">
                Last Seen
              </th>

              <th className="px-6 py-3 text-left text-sm font-semibold text-gray-300">
                Confidence
              </th>

              <th className="px-6 py-3 text-center text-sm font-semibold text-gray-300">
                Action
              </th>
            </tr>
          </thead>

          <tbody>
            {paginatedIdentities.map((identity) => (
              <tr
                key={identity.id}
                className="border-b border-[#333] hover:bg-[#333]/50 transition-colors cursor-pointer"
                onClick={() =>
                  router.push(`/analytics/identities/${identity.id}`)
                }
              >
                <td className="px-6 py-4 text-sm font-mono text-cyan-400">
                  {identity.identityId}
                </td>

                <td className="px-6 py-4 text-sm text-gray-300">
                  {identity.detectionCount}
                </td>

                <td className="px-6 py-4 text-sm text-gray-400">
                  {formatDate(identity.firstSeen)}
                </td>

                <td className="px-6 py-4 text-sm text-gray-400">
                  {formatDate(identity.lastSeen)}
                </td>

                <td className="px-6 py-4 text-sm">
                  <Badge
                    className={`${getConfidenceBadge(identity.confidence)} border-0`}
                  >
                    {identity.confidence}
                  </Badge>
                </td>

                <td className="px-6 py-4 text-center">
                  <ArrowRight size={16} className="inline text-cyan-400" />
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* ================= PAGINATION ================= */}

      {totalPages > 1 && (
        <div className="px-6 py-4 border-t border-[#333] flex items-center justify-between">
          <p className="text-sm text-gray-400">
            Page {currentPage} of {totalPages}
          </p>

          <div className="flex gap-2">
            <button
              onClick={() => onPageChange?.(Math.max(1, currentPage - 1))}
              disabled={currentPage === 1}
              className="px-3 py-1 text-sm rounded bg-[#333] text-gray-300 hover:bg-[#444] disabled:opacity-50 disabled:cursor-not-allowed"
            >
              Previous
            </button>

            <button
              onClick={() =>
                onPageChange?.(Math.min(totalPages, currentPage + 1))
              }
              disabled={currentPage === totalPages}
              className="px-3 py-1 text-sm rounded bg-[#333] text-gray-300 hover:bg-[#444] disabled:opacity-50 disabled:cursor-not-allowed"
            >
              Next
            </button>
          </div>
        </div>
      )}
    </Card>
  );
}
