"use client";

import { useEffect, useState } from "react";
import { getIdentities } from "@/lib/api/identities";
import { IdentityTable } from "@/components/identity-table";

/* ================= TYPES MATCH BACKEND ================= */

interface Identity {
  id: string;
  identityId: string;
  confidence: string;
  consistency: number;
  detectionCount: number;
  firstSeen: string;
  lastSeen: string;
}

/* ======================================================= */

export default function IdentitiesPage() {
  const [identities, setIdentities] = useState<Identity[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [currentPage, setCurrentPage] = useState(1);

  useEffect(() => {
    const fetchIdentities = async () => {
      setIsLoading(true);

      try {
        const data = await getIdentities();
        setIdentities(data);
      } catch (error) {
        console.error("Error fetching identities:", error);
      } finally {
        setIsLoading(false);
      }
    };

    fetchIdentities();
  }, []);

  /* ================= CONFIDENCE CALCULATIONS ================= */

  const highConfidence = identities.filter(
    (i) => parseFloat(i.confidence) >= 0.9,
  ).length;

  const mediumConfidence = identities.filter((i) => {
    const c = parseFloat(i.confidence);
    return c >= 0.7 && c < 0.9;
  }).length;

  const lowConfidence = identities.filter(
    (i) => parseFloat(i.confidence) < 0.7,
  ).length;

  /* ============================================================ */

  return (
    <div className="space-y-6 p-6">
      {/* ================= PAGE HEADER ================= */}

      <div>
        <h1 className="text-3xl font-bold text-white mb-2">Identities</h1>
        <p className="text-gray-400">
          Monitor detected identities across all surveillance cameras
        </p>
      </div>

      {/* ================= METRICS ================= */}

      <div className="grid grid-cols-4 gap-4">
        <div className="bg-[#222] border border-[#333] rounded-lg p-4">
          <p className="text-sm text-gray-400">Total Identities</p>
          <p className="text-2xl font-bold text-white mt-1">
            {identities.length}
          </p>
        </div>

        <div className="bg-[#222] border border-[#333] rounded-lg p-4">
          <p className="text-sm text-gray-400">High Confidence</p>
          <p className="text-2xl font-bold text-green-400 mt-1">
            {highConfidence}
          </p>
        </div>

        <div className="bg-[#222] border border-[#333] rounded-lg p-4">
          <p className="text-sm text-gray-400">Medium Confidence</p>
          <p className="text-2xl font-bold text-yellow-400 mt-1">
            {mediumConfidence}
          </p>
        </div>

        <div className="bg-[#222] border border-[#333] rounded-lg p-4">
          <p className="text-sm text-gray-400">Low Confidence</p>
          <p className="text-2xl font-bold text-red-400 mt-1">
            {lowConfidence}
          </p>
        </div>
      </div>

      {/* ================= TABLE ================= */}

      <IdentityTable
        identities={identities}
        isLoading={isLoading}
        currentPage={currentPage}
        onPageChange={setCurrentPage}
      />
    </div>
  );
}
